// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

import { ModuleWrapper, Memory } from '@stdlib/types/wasm';

/**
* Interface defining a module constructor which is both "newable" and "callable".
*/
interface ModuleConstructor {
	/**
	* Returns a new WebAssembly module wrapper instance which uses the provided WebAssembly memory instance as its underlying memory.
	*
	* @param mem - WebAssembly memory instance
	* @returns module wrapper instance
	*
	* @example
	* var Memory = require( '@stdlib/wasm/memory' );
	* var oneTo = require( '@stdlib/array/one-to' );
	* var zeros = require( '@stdlib/array/zeros' );
	* var bytesPerElement = require( '@stdlib/ndarray/base/bytes-per-element' );
	*
	* // Create a new memory instance with an initial size of 10 pages (640KiB) and a maximum size of 100 pages (6.4MiB):
	* var mem = new Memory({
	*     'initial': 10,
	*     'maximum': 100
	* });
	*
	* // Create a new routine:
	* var mod = new dmskmax.Module( mem );
	* // returns <Module>
	*
	* // Initialize the routine:
	* mod.initializeSync();
	*
	* // Specify a vector length:
	* var N = 5;
	*
	* // Define pointers (i.e., byte offsets) for storing the input array and mask:
	* var xptr = 0;
	* var mptr = N * bytesPerElement( 'float64' );
	*
	* // Write array values to module memory:
	* mod.write( xptr, oneTo( N, 'float64' ) );
	* mod.write( mptr, zeros( N, 'uint8' ) );
	*
	* // Perform computation:
	* var v = mod.main( N, xptr, 1, mptr, 1 );
	* // returns 5.0
	*/
	new( mem: Memory ): Module; // newable

	/**
	* Returns a new WebAssembly module wrapper instance which uses the provided WebAssembly memory instance as its underlying memory.
	*
	* @param mem - WebAssembly memory instance
	* @returns module wrapper instance
	*
	* @example
	* var Memory = require( '@stdlib/wasm/memory' );
	* var oneTo = require( '@stdlib/array/one-to' );
	* var zeros = require( '@stdlib/array/zeros' );
	* var bytesPerElement = require( '@stdlib/ndarray/base/bytes-per-element' );
	*
	* // Create a new memory instance with an initial size of 10 pages (640KiB) and a maximum size of 100 pages (6.4MiB):
	* var mem = new Memory({
	*     'initial': 10,
	*     'maximum': 100
	* });
	*
	* // Create a new routine:
	* var mod = dmskmax.Module( mem );
	* // returns <Module>
	*
	* // Initialize the routine:
	* mod.initializeSync();
	*
	* // Specify a vector length:
	* var N = 5;
	*
	* // Define pointers (i.e., byte offsets) for storing the input array and mask:
	* var xptr = 0;
	* var mptr = N * bytesPerElement( 'float64' );
	*
	* // Write array values to module memory:
	* mod.write( xptr, oneTo( N, 'float64' ) );
	* mod.write( mptr, zeros( N, 'uint8' ) );
	*
	* // Perform computation:
	* var v = mod.main( N, xptr, 1, mptr, 1 );
	* // returns 5.0
	*/
	( mem: Memory ): Module; // callable
}

/**
* Interface describing a `dmskmax` WebAssembly module.
*/
interface Module extends ModuleWrapper {
	/**
	* Computes the maximum value of a double-precision floating-point strided array according to a mask.
	*
	* @param N - number of indexed elements
	* @param xptr - input array pointer (i.e., byte offset)
	* @param strideX - `x` stride length
	* @param mptr - mask array pointer (i.e., byte offset)
	* @param strideMask - `mask` stride length
	* @returns maximum value
	*
	* @example
	* var Memory = require( '@stdlib/wasm/memory' );
	* var oneTo = require( '@stdlib/array/one-to' );
	* var zeros = require( '@stdlib/array/zeros' );
	* var bytesPerElement = require( '@stdlib/ndarray/base/bytes-per-element' );
	*
	* // Create a new memory instance with an initial size of 10 pages (640KiB) and a maximum size of 100 pages (6.4MiB):
	* var mem = new Memory({
	*     'initial': 10,
	*     'maximum': 100
	* });
	*
	* // Create a new routine:
	* var mod = new dmskmax.Module( mem );
	* // returns <Module>
	*
	* // Initialize the routine:
	* mod.initializeSync();
	*
	* // Specify a vector length:
	* var N = 5;
	*
	* // Define pointers (i.e., byte offsets) for storing the input array and mask:
	* var xptr = 0;
	* var mptr = N * bytesPerElement( 'float64' );
	*
	* // Write array values to module memory:
	* mod.write( xptr, oneTo( N, 'float64' ) );
	* mod.write( mptr, zeros( N, 'uint8' ) );
	*
	* // Perform computation:
	* var v = mod.main( N, xptr, 1, mptr, 1 );
	* // returns 5.0
	*/
	main( N: number, xptr: number, strideX: number, mptr: number, strideMask: number ): number;

	/**
	* Computes the maximum value of a double-precision floating-point strided array according to a mask using alternative indexing semantics.
	*
	* @param N - number of indexed elements
	* @param xptr - input array pointer (i.e., byte offset)
	* @param strideX - `x` stride length
	* @param offsetX - starting index for `x`
	* @param mptr - mask array pointer (i.e., byte offset)
	* @param strideMask - `mask` stride length
	* @param offsetMask - starting index for `mask`
	* @returns maximum value
	*
	* @example
	* var Memory = require( '@stdlib/wasm/memory' );
	* var oneTo = require( '@stdlib/array/one-to' );
	* var zeros = require( '@stdlib/array/zeros' );
	* var bytesPerElement = require( '@stdlib/ndarray/base/bytes-per-element' );
	*
	* // Create a new memory instance with an initial size of 10 pages (640KiB) and a maximum size of 100 pages (6.4MiB):
	* var mem = new Memory({
	*     'initial': 10,
	*     'maximum': 100
	* });
	*
	* // Create a new routine:
	* var mod = new dmskmax.Module( mem );
	* // returns <Module>
	*
	* // Initialize the routine:
	* mod.initializeSync();
	*
	* // Specify a vector length:
	* var N = 5;
	*
	* // Define pointers (i.e., byte offsets) for storing the input array and mask:
	* var xptr = 0;
	* var mptr = N * bytesPerElement( 'float64' );
	*
	* // Write array values to module memory:
	* mod.write( xptr, oneTo( N, 'float64' ) );
	* mod.write( mptr, zeros( N, 'uint8' ) );
	*
	* // Perform computation:
	* var v = mod.ndarray( N, xptr, 1, 0, mptr, 1, 0 );
	* // returns 5.0
	*/
	ndarray( N: number, xptr: number, strideX: number, offsetX: number, mptr: number, strideMask: number, offsetMask: number ): number;
}

/**
* Interface describing `dmskmax`.
*/
interface Routine extends ModuleWrapper {
	/**
	* Computes the maximum value of a double-precision floating-point strided array according to a mask.
	*
	* @param N - number of indexed elements
	* @param x - input array
	* @param strideX - `x` stride length
	* @param mask - mask array
	* @param strideMask - `mask` stride length
	* @returns maximum value
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	* var Uint8Array = require( '@stdlib/array/uint8' );
	*
	* var x = new Float64Array( [ 1.0, -2.0, 4.0, 2.0 ] );
	* var mask = new Uint8Array( [ 0, 0, 1, 0 ] );
	*
	* var v = dmskmax.main( x.length, x, 1, mask, 1 );
	* // returns 2.0
	*/
	main( N: number, x: Float64Array, strideX: number, mask: Uint8Array, strideMask: number ): number;

	/**
	* Computes the maximum value of a double-precision floating-point strided array according to a mask using alternative indexing semantics.
	*
	* @param N - number of indexed elements
	* @param x - input array
	* @param strideX - `x` stride length
	* @param offsetX - starting index for `x`
	* @param mask - mask array
	* @param strideMask - `mask` stride length
	* @param offsetMask - starting index for `mask`
	* @returns maximum value
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	* var Uint8Array = require( '@stdlib/array/uint8' );
	*
	* var x = new Float64Array( [ 1.0, -2.0, 4.0, 2.0 ] );
	* var mask = new Uint8Array( [ 0, 0, 1, 0 ] );
	*
	* var v = dmskmax.ndarray( x.length, x, 1, 0, mask, 1, 0 );
	* // returns 2.0
	*/
	ndarray( N: number, x: Float64Array, strideX: number, offsetX: number, mask: Uint8Array, strideMask: number, offsetMask: number ): number;

	/**
	* Returns a new WebAssembly module wrapper instance which uses the provided WebAssembly memory instance as its underlying memory.
	*
	* @param mem - WebAssembly memory instance
	* @returns module wrapper instance
	*
	* @example
	* var Memory = require( '@stdlib/wasm/memory' );
	* var oneTo = require( '@stdlib/array/one-to' );
	* var zeros = require( '@stdlib/array/zeros' );
	* var bytesPerElement = require( '@stdlib/ndarray/base/bytes-per-element' );
	*
	* // Create a new memory instance with an initial size of 10 pages (640KiB) and a maximum size of 100 pages (6.4MiB):
	* var mem = new Memory({
	*     'initial': 10,
	*     'maximum': 100
	* });
	*
	* // Create a new routine:
	* var mod = new dmskmax.Module( mem );
	* // returns <Module>
	*
	* // Initialize the routine:
	* mod.initializeSync();
	*
	* // Specify a vector length:
	* var N = 5;
	*
	* // Define pointers (i.e., byte offsets) for storing the input array and mask:
	* var xptr = 0;
	* var mptr = N * bytesPerElement( 'float64' );
	*
	* // Write array values to module memory:
	* mod.write( xptr, oneTo( N, 'float64' ) );
	* mod.write( mptr, zeros( N, 'uint8' ) );
	*
	* // Perform computation:
	* var v = mod.main( N, xptr, 1, mptr, 1 );
	* // returns 5.0
	*/
	Module: ModuleConstructor;
}

/**
* Computes the maximum value of a double-precision floating-point strided array according to a mask.
*
* @param N - number of indexed elements
* @param x - input array
* @param strideX - `x` stride length
* @param mask - mask array
* @param strideMask - `mask` stride length
* @returns maximum value
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var Uint8Array = require( '@stdlib/array/uint8' );
*
* var x = new Float64Array( [ 1.0, -2.0, 4.0, 2.0 ] );
* var mask = new Uint8Array( [ 0, 0, 1, 0 ] );
*
* var v = dmskmax.main( x.length, x, 1, mask, 1 );
* // returns 2.0
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var Uint8Array = require( '@stdlib/array/uint8' );
*
* var x = new Float64Array( [ 1.0, -2.0, 4.0, 2.0 ] );
* var mask = new Uint8Array( [ 0, 0, 1, 0 ] );
*
* var v = dmskmax.ndarray( x.length, x, 1, 0, mask, 1, 0 );
* // returns 2.0
*/
declare var dmskmax: Routine;


// EXPORTS //

export = dmskmax;
